var e=[{title:`Partea superioară a corpului`,text:`Mușchii pectorali ajută la împingerea brațelor înainte sau peste trunchi, ca la flotări și la împingerile de piept. Marele dorsal și ceilalți mușchi ai spatelui ajută la tragerea brațelor și la controlul omoplaților la ramat și la tracțiuni. Deltoizii ajută la ridicarea și la mișcarea brațelor. Bicepșii flectează cotul și ajută la unele mișcări de tragere, iar tricepșii extind cotul în timpul împingerilor.`},{title:`Partea inferioară a corpului`,text:`Cvadricepșii extind genunchiul și ajută la genuflexiune, la pășit și la fandare. Mușchii fesieri extind sau stabilizează șoldul, iar flexiile din șold și urcările pe treaptă îi pot solicita. Mușchii din spatele coapsei flectează genunchiul și ajută la extensia șoldului. Mușchii gambei produc flexia plantară a gleznei pentru mers, alergare și ridicări pe vârfuri. Adductorii și abductorii șoldului ajută la controlul poziției piciorului și la stabilitatea bazinului.`},{title:`Trunchiul (zona centrală)`,text:`Dreptul abdominal, oblicii, mușchii abdominali profunzi, extensorii coloanei și câțiva mușchi din jurul bazinului ajută la transmiterea forței și la rezistența în fața ei. Plank-urile, căratul și flexiile din șold controlate solicită stabilitatea trunchiului în direcții diferite. „Abdomenul” vizibil este doar o parte a acestui sistem.`},{title:`Suprapunerea dintre exerciții`,text:`O genuflexiune lucrează mai mult decât cvadricepșii, iar ramatul lucrează mai mult decât dorsalii. Priza, unghiul trunchiului, amplitudinea mișcării și propria ta anatomie schimbă care mușchi fac mai mult din muncă. Organizează săptămâna unui începător în jurul genuflexiunilor, flexiilor din șold, fandărilor, împingerilor, tragerilor și lucrului pentru zona centrală și nu atribui fiecare antrenament unui singur mușchi.`},{title:`Folosind TrainUp`,text:`Pagina fiecărui exercițiu din Exerciții arată tiparul de mișcare și mușchii lucrați, ceea ce te ajută să acoperi tot corpul cu un număr mic de exerciții. Lucrul de izolare poate umple o lacună anume, dar nu înlocuiește învățarea mișcărilor de bază cu mai multe articulații.`}];var l=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Prezentare HHS despre condiția fizică`,url:`https://www.cdc.gov/physical-activity-basics/about/index.html`}];var r={sections:e,sources:l};export{r as default,e as sections,l as sources};